namespace $ { $mol_style_attach( "bog/kit/shell/shell.view.css",
 "/*\n\tThe Kit theme — canvas.\n\n\tShells stacked on shells: a case, the panel of a page, and the raised parts\n\tyou touch. Nothing is outlined and nothing casts a shadow — a surface is told\n\tapart from the one under it by tone, by its corner, and by the space around\n\tit. Corners are generous and the things you press are shaped like keys.\n\n\tValues only; the names live in kit.ts.\n*/\n\n:root {\n\t--bog_kit_font_text: 'IBM Plex Sans', 'Segoe UI', system-ui, sans-serif;\n\t--bog_kit_font_code: 'IBM Plex Mono', ui-monospace, 'SF Mono', Menlo, Consolas, monospace;\n}\n\n[bog_kit_shell] {\n\t--bog_kit_font_text: 'IBM Plex Sans', 'Segoe UI', system-ui, sans-serif;\n\t--bog_kit_font_code: 'IBM Plex Mono', ui-monospace, 'SF Mono', Menlo, Consolas, monospace;\n\n\t--bog_kit_case: #dfe3e9;\n\t--bog_kit_panel: #eef1f5;\n\t--bog_kit_raise: #ffffff;\n\t--bog_kit_ink: #13161b;\n\t--bog_kit_ink_soft: #656d7a;\n\t--bog_kit_key: #1b53d0;\n\t--bog_kit_key_ink: #ffffff;\n\n\t--bog_kit_round_panel: 22px;\n\t--bog_kit_round_field: 16px;\n\t--bog_kit_round_pill: 999px;\n\n\t--bog_kit_lift: none;\n\t--bog_kit_lift_high: none;\n\t--bog_kit_sink: none;\n\t--bog_kit_seam: #d2d8e1;\n\n\tfont-family: var(--bog_kit_font_text);\n\tfont-size: 1rem;\n\tline-height: 1.6rem;\n\n\t--mol_gap_page: 2rem;\n\t--mol_gap_block: 0.75rem;\n\t--mol_gap_text: 0.5rem 0.875rem;\n\t--mol_gap_round: 12px;\n\t--mol_gap_space: 0.375rem;\n\t--mol_gap_blur: 0rem;\n}\n\n/*\n\tNight. The ink is deliberately short of white — a full-strength white on a\n\tdark panel glares and smears at small sizes. It sits around 80% lightness,\n\twhich still clears 9:1 against the panel.\n*/\n[bog_kit_shell][mol_theme=\"$mol_theme_dark\"] {\n\t--bog_kit_case: #12161c;\n\t--bog_kit_panel: #1a1f27;\n\t--bog_kit_raise: #232932;\n\t--bog_kit_ink: #c6ccd5;\n\t--bog_kit_ink_soft: #7f8794;\n\t--bog_kit_key: #7ba4ff;\n\t--bog_kit_key_ink: #12161c;\n\t--bog_kit_seam: #0d1116;\n}\n\n/*\n\tStock components we did not subclass read --mol_theme_*, so the palette is\n\tmapped onto it and they follow along. Two attributes, so this always\n\toutweighs the theme.css rule sitting on the very same node.\n*/\n[bog_kit_shell][mol_theme] {\n\t--mol_theme_hue: 230deg;\n\t--mol_theme_hue_spread: 120deg;\n\n\t--mol_theme_back: var(--bog_kit_case);\n\t--mol_theme_card: var(--bog_kit_raise);\n\t--mol_theme_field: var(--bog_kit_raise);\n\t--mol_theme_hover: #7f879424;\n\t--mol_theme_text: var(--bog_kit_ink);\n\t--mol_theme_shade: var(--bog_kit_ink_soft);\n\t--mol_theme_line: var(--bog_kit_seam);\n\t--mol_theme_focus: var(--bog_kit_key);\n\t--mol_theme_control: var(--bog_kit_key);\n\t--mol_theme_current: var(--bog_kit_key);\n\t--mol_theme_special: var(--bog_kit_key);\n\t--mol_theme_spirit: var(--bog_kit_raise);\n}\n\n[bog_kit_shell][mol_theme=\"$mol_theme_light\"] {\n\t--mol_theme_luma: 1;\n\t--mol_theme_image: none;\n}\n\n[bog_kit_shell][mol_theme=\"$mol_theme_dark\"] {\n\t--mol_theme_luma: -1;\n\t--mol_theme_image: invert(1) hue-rotate(180deg);\n}\n\n/*\n\tDepth is a variable, so it has to be applied where a variable can stand for a\n\twhole shadow. This tone carries none, but the hooks stay: which raised part\n\tgets which lift is a decision of the system, not of the palette.\n*/\n[bog_kit_shell] [bog_kit_card],\n[bog_kit_shell] [bog_kit_button],\n[bog_kit_shell] [bog_kit_button_copy],\n[bog_kit_shell] [bog_kit_check_icon],\n[bog_kit_shell] [bog_kit_select_trigger],\n[bog_kit_shell] [bog_kit_check_list_option]:not([mol_check_checked]) {\n\tbox-shadow: var(--bog_kit_lift);\n}\n\n[bog_kit_shell] [bog_kit_button_major],\n[bog_kit_shell] [bog_kit_check_list_option][mol_check_checked] {\n\tbox-shadow: var(--bog_kit_lift_high);\n}\n\n[bog_kit_shell] [bog_kit_switch_option][mol_check_checked],\n[bog_kit_shell] [bog_kit_lights_pick_option][mol_check_checked] {\n\tbox-shadow: var(--bog_kit_lift);\n}\n\n[bog_kit_shell] [bog_kit_input],\n[bog_kit_shell] [bog_kit_switch],\n[bog_kit_shell] [bog_kit_lights_pick] {\n\tbox-shadow: var(--bog_kit_sink);\n}\n\n[bog_kit_shell] [bog_kit_input]:focus,\n[bog_kit_shell] [bog_kit_select_trigger]:focus-visible {\n\tbox-shadow: 0 0 0 2px var(--bog_kit_key);\n}\n\n/*\n\tThe plate everything is laid out on. $mol_book2 frames each page with a pale\n\tinset and marks the seams between them with dashes; here the pages are panels\n\twith the case showing through between them.\n*/\n[bog_kit_shell][mol_book2],\n[bog_kit_shell] [mol_book2] {\n\tgap: 2px;\n\tbackground: var(--bog_kit_case);\n\t/*\n\t\t$mol_scroll asks for `contain: content`, which is layout + paint + style —\n\t\tand anything with layout or paint containment becomes the containing block\n\t\tfor its `position: fixed` children. The level indicator was then pinned to\n\t\tthe scrolled content rather than to the screen, so it slid away with the\n\t\tfirst column and only ever showed up on the first level. Style containment\n\t\tis all this needs.\n\t*/\n\tcontain: style;\n}\n\n[bog_kit_shell][mol_book2] > [mol_page],\n[bog_kit_shell] [mol_book2] > [mol_page] {\n\tbox-shadow: none;\n}\n\n[bog_kit_shell][mol_book2] > [mol_view]::before,\n[bog_kit_shell][mol_book2] > [mol_view]::after,\n[bog_kit_shell] [mol_book2] > [mol_view]::before,\n[bog_kit_shell] [mol_book2] > [mol_view]::after {\n\tdisplay: none;\n\tcontent: none;\n}\n\n/* Icons come with a drop shadow of their own. The shells carry the depth. */\n[bog_kit_shell] [mol_icon] {\n\tfilter: none;\n}\n\n[bog_kit_shell] [mol_pop_bubble] {\n\tbackground: var(--bog_kit_raise);\n\tborder-radius: var(--bog_kit_round_panel);\n\tbox-shadow: 0 0 0 1px var(--bog_kit_seam);\n\tpadding: 0.375rem;\n}\n\n/*\n\tA minor button inside a bubble is a row of a menu, not a key — the choice is\n\tthe list, and raising every line would make it unreadable.\n*/\n[bog_kit_shell] [mol_pop_bubble] [bog_kit_button] {\n\tbox-shadow: none;\n\tbackground: transparent;\n\tcolor: var(--bog_kit_ink);\n\tborder-radius: var(--bog_kit_round_field);\n}\n\n[bog_kit_shell] [mol_pop_bubble] [bog_kit_button]:hover {\n\tbox-shadow: none;\n\tbackground: var(--bog_kit_panel);\n\tcolor: var(--bog_kit_ink);\n}\n\n/* A heading in $mol_text is an anchor; it should read as a heading. */\n[bog_kit_shell] [mol_text_header_link] {\n\tcolor: inherit;\n\tbackground: transparent;\n\tpadding-left: 0;\n\tmin-height: 0;\n}\n\n[bog_kit_shell] [mol_view]::selection {\n\tbackground: var(--bog_kit_key);\n\tcolor: var(--bog_kit_key_ink);\n}\n\n/*\n\t=== The frame ===\n\n\tBehaving like an installed app rather than like a page: platform metrics, the\n\tsafe areas of a phone, and one screen per column.\n*/\n\n/* Platform metrics. The system face at the system size is half the tell. */\n[bog_kit_shell][bog_kit_platform=\"ios\"] {\n\t--bog_kit_font_text: -apple-system, BlinkMacSystemFont, 'SF Pro Text', system-ui, sans-serif;\n\tfont-size: 17px;\n\tline-height: 22px;\n\t--bog_kit_round_field: 12px;\n\t--bog_kit_round_panel: 18px;\n}\n\n[bog_kit_shell][bog_kit_platform=\"md\"] {\n\t--bog_kit_font_text: Roboto, 'Noto Sans', system-ui, sans-serif;\n\tfont-size: 16px;\n\tline-height: 24px;\n\t--bog_kit_round_field: 16px;\n\t--bog_kit_round_panel: 20px;\n}\n\n/*\n\tTouch behaviour. A page that highlights on tap, shows a callout on long\n\tpress or lets you select the chrome reads as a web page instantly.\n*/\n[bog_kit_shell] {\n\t-webkit-tap-highlight-color: transparent;\n\t-webkit-touch-callout: none;\n\toverscroll-behavior: none;\n}\n\n[bog_kit_shell] [mol_view] {\n\tuser-select: none;\n\t-webkit-user-select: none;\n}\n\n[bog_kit_shell] [mol_text],\n[bog_kit_shell] [mol_string],\n[bog_kit_shell] [mol_textarea] {\n\tuser-select: text;\n\t-webkit-user-select: text;\n}\n\n/* The notch and the home indicator belong to the chrome, not to the content. */\n[bog_kit_shell] [bog_kit_page_head] {\n\tpadding-top: calc(0.75rem + env(safe-area-inset-top));\n\tpadding-left: calc(1rem + env(safe-area-inset-left));\n\tpadding-right: calc(0.75rem + env(safe-area-inset-right));\n}\n\n[bog_kit_shell] [bog_kit_page_body_content] {\n\tpadding-bottom: calc(2.5rem + env(safe-area-inset-bottom));\n\tpadding-left: calc(1.25rem + env(safe-area-inset-left));\n\tpadding-right: calc(1.25rem + env(safe-area-inset-right));\n}\n\n[bog_kit_shell] [bog_kit_pager] {\n\ttop: env(safe-area-inset-top);\n}\n\n/*\n\tOne screen per column. The browser's own momentum and snapping do the paging,\n\tso the gesture belongs to the platform rather than to us.\n*/\n@media (max-width: 45rem) {\n\n\t[bog_kit_shell][mol_book2],\n\t[bog_kit_shell] [mol_book2] {\n\t\tscroll-snap-type: x mandatory;\n\t}\n\n\t[bog_kit_shell][mol_book2] > article[mol_page],\n\t[bog_kit_shell] [mol_book2] > article[mol_page] {\n\t\tflex: 0 0 100%;\n\t\tmin-width: 100%;\n\t\tscroll-snap-align: start;\n\t\tscroll-snap-stop: always;\n\t}\n\n}\n\n@media (prefers-reduced-motion: reduce) {\n\t[bog_kit_shell] * {\n\t\ttransition-duration: 0.01ms !important;\n\t\tanimation-duration: 0.01ms !important;\n\t}\n}\n"
) }